@Composable
fun Icon(icon: NeboIcon, color: Color, size: Dp = 22.dp, modifier: Modifier = Modifier, filled: Boolean = false) {
    val path = remember(icon, filled) { if (filled) icon.fillPath else icon.lightPath }
    Canvas(modifier.size(size)) {
        scale(this.size.minDimension / 256f, pivot = Offset.Zero) { drawPath(path, color) }
    }
}
